public class LinkedBT<T> implements BinaryTree<T> {
  protected TreeNode<T> root; 
// reference to root node
  protected static class TreeNode<T> {
    T element; 
// pointer to element object
    TreeNode<T> left; 
// pointer to left subtree
    TreeNode<T> right; 
// pointer to right subtree
    // Constructs a tree node object with no children
    public TreeNode(T element) { this (element, null, null); }
    // Constructs a tree node with left and right subtrees
    public TreeNode(T element, TreeNode<T> left, TreeNode<T> right) {
      this.element = element;
      this.left = left;
      this.right = right;
