public int size() {
  int lsize = (left != null)? left.size() : 0;
  int rsize = (right != null)? right.size() : 0;
  return lsize + rsize + 1;
                                    // +1 for this tree node
}

// Recursively computes and returns the height of the binary tree
public int height() {
  int lheight = (left != null)? left.height() + 1 : 0;
  int rheight = (right != null)? right.height() + 1 : 0;
  return Math.max(lheight, rheight);
}

