// Returns a list of elements along the level-order tree traversal
public List<T> levelOrder() {
  List<T> list = new LinkedList<>(); 
// list of elements
  Queue<TreeNode<T>> queue = new LinkedList<>(); // queue of nodes
  if (root != null) queue.add(root); 
// add root node to queue 
  while (!queue.isEmpty()) { 
// queue has tree nodes
    TreeNode<T> node = queue.remove(); // remove front node
    list.add(node.element); 
// add element to list
    // add left and right nodes to queue
    if (node.left != null) queue.add(node.left); 
    if (node.right != null) queue.add(node.right);
  }
  return list;
}
